class Complex {
	constructor(re, im) {
		this.re = re;
		this.im = im;
	}
	equals(z) {
		return this.re == z.re && this.im == z.im;
	}

	modulus() {
		return Math.hypot(this.re, this.im);
	}
	arg() {
		return Math.atan2(this.im, this.re);
	}

	mul(z) {
		return new Complex(this.re * z.re - this.im * z.im, this.re * z.im + this.im * z.re);
	}
	mulS(s) {
		return new Complex(this.re * s, this.im * s);
	}
	div(z) {
		let c = this.re;
		let d = this.im;
		let a = z.re;
		let b = z.im;
		return new Complex(a * c + b * d, a * d - b * c).divS(a * a + b * b);
	}
	divS(s) {
		return new Complex(this.re / s, this.im / s);
	}
	plus(z) {
		return new Complex(this.re + z.re, this.im + z.im);
	}
	minus(z) {
		return new Complex(this.re - z.re, this.im - z.im);
	}

	static get ZERO() {
		return new Complex(0, 0);
	}
	static get ONE() {
		return new Complex(1, 0);
	}
	static get I() {
		return new Complex(0, 1);
	}
	static get J() {
		return new Complex(0, -1);
	} 

	powS(s) {
		return this.pow(new Complex(s, 0));
	}

	pow(z) {
		if (z.equals(Complex.ZERO)) {
			return Complex.ONE;
		}
		if (this.equals(Complex.ZERO)) {
			return Complex.ZERO;
		}
		let rho = this.modulus();
		let theta = this.arg();
		let newRho = z.re * theta + z.im * Math.log(rho);
		let t = Math.pow(rho, z.re) * Math.exp(-z.im * theta);
		return Complex.euler(newRho).mulS(t);
	}

	exp() {
		return Complex.euler(this.im).mulS(Math.exp(this.re));
	}

	sin() {
		return this.mul(Complex.I).exp().minus(this.mul(Complex.J).exp()).div(Complex.I.mulS(2));
	}

	cos() {
		return this.mul(Complex.I).exp().plus(this.mul(Complex.J).exp()).divS(2);
	}

	static euler(t) {
		return new Complex(Math.cos(t), Math.sin(t));
	}
}

