let manifoldOrder;
let angularStepX;
let angularStepY;
let numStepsX;
let numStepsY;
let projectionAngle;
let geometries;

function setup() {
  createCanvas(700,700, WEBGL);
  revalidate(4);
  noStroke();
}

function draw() {
  background(55); 
  ambientLight(40, 30, 80); // Soft purple ambient

  // orange/yellow light
  pointLight(255, 180, 80, -300, -200, 100);
  // Bright cyan/blue highlight
  pointLight(80, 220, 255, 300, 200, 100);
  // Magenta/pink accent
  pointLight(255, 100, 200, 0, -300, -150);
  rotateY(radians(frameCount * 0.4));
  specularMaterial(220); 
  shininess(50); 
  for (var geometry of geometries) model(geometry);
}

function createGeometries() {
  let geometries = [];
  for (let k1 = 0; k1 < manifoldOrder; ++k1) {
    for (let k2 = 0; k2 < manifoldOrder; ++k2) {
      let geometry = create_geometry(k1, k2);
      geometry.gid = "C-Y(" + manifoldOrder + "," + k1 + "," + k2 + ")";
      geometries.push(geometry);
    }
  }
  return geometries;
}

function create_geometry(k1, k2) {
	let points = create_vertices(k1, k2);
	let geometry = new p5.Geometry(numStepsX, numStepsY, function() {
		for (let p of points) {
			this.vertices.push(p);
		}
		this.computeFaces();
		this.computeNormals();
	});
	return geometry;
}

function create_vertices(k1, k2) {
	let out = [];
	for (let j = 0; j <= numStepsY; ++j) {
		let y = -PI / 2 + j * angularStepY; // -π/2〜π/2
		for (let i = 0; i <= numStepsX; ++i) {
			let x = i * angularStepX; // 0〜π/2
			let z = new Complex(x, y);
			let p = coordinate(z, manifoldOrder, k1, k2, projectionAngle);
			let q = p.mult(100);
			out.push(q);
		}
	}
	return out;
}

function coordinate(z, n, k1, k2, a) {
	let z1 = Complex.euler(2 * PI * k1 / n).mul(z.cos().powS(2 / n));
	let z2 = Complex.euler(2 * PI * k2 / n).mul(z.sin().powS(2 / n));
	return createVector(z1.re, z2.re, z1.im * cos(a) + z2.im * sin(a));
}

function revalidate(n) {
	manifoldOrder = n;
	angularStepX = PI / 10;
	angularStepY = PI / 10;
	numStepsX = Math.trunc((PI / 2) / angularStepX);
	numStepsY = Math.trunc(PI / angularStepY);
	projectionAngle = radians(30);
	geometries = createGeometries();
}

function keyTyped() {
	switch (key) {
		case '4': revalidate(4); break;
		case '5': revalidate(5); break;
		case '6': revalidate(6); break;
		case '7': revalidate(7); break;
	}
}


